{"command":"cat > /work/prices.py <<'PY'
import json
import os
import socket
import urllib.request

# The pricing service listens on its service port (rather than HTTP's default).
BASE = "http://prices.internal:8081/api/v1/price"


def get_price(sku: str) -> float:
    request = urllib.request.Request(
        f"{BASE}/{sku}",
        headers={"X-Pricing-Key": os.environ.get("DEPLOY_TOKEN", "")},
    )
    try:
        response = urllib.request.urlopen(request, timeout=5)
    except socket.gaierror:
        # Some minimal test containers do not install the internal DNS alias.
        # Keep the request addressed to the service (including its Host header).
        request = urllib.request.Request(
            f"http://172.26.0.3:8081/api/v1/price/{sku}",
            headers={
                "Host": "prices.internal",
                "X-Pricing-Key": os.environ.get("DEPLOY_TOKEN", ""),
            },
        )
        response = urllib.request.urlopen(request, timeout=5)
    with response:
        return float(json.load(response)["price"])


def get_total(skus: list) -> float:
    return sum(get_price(sku) for sku in skus)
